async def test_api_object_channel_on_object_updated_delivers_contract_valid_payloads(rig):
    client, socket = rig
    await client.register_scenario(
        {
            "topic": "api:object:test-id",
            "onJoin": [
                {"type": "autoReply"},
                {"type": "autoPush", "event": "object_updated"},
            ],
        }
    )
    channel = await ApiObjectChannel.join_by_id(socket, "test-id")
    future: asyncio.Future = asyncio.get_event_loop().create_future()

    def handler(payload):
        if not future.done():
            future.set_result(payload)

    channel.on_object_updated(handler)
    payload = await asyncio.wait_for(future, timeout=1.0)
    assert payload is not None


